#include <stdio.h>

int N, K;
int a[500005];

long long f(int T) {
    if (T < 0) return 0;
    long long cnt = 0;
    int sum = 0;
    int l = 0;
    for (int r = 0; r < N; r++) {
        sum += a[r];
        while (sum > T) {
            sum -= a[l];
            l++;
        }
        cnt += (long long)(r - l + 1);
    }
    return cnt;
}

int main() {
    scanf("%d %d", &N, &K);
    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
    }

    long long ans = f(K);
    if (K > 0) ans -= f(K - 1);

    printf("%lld\n", ans);
    return 0;
}
